# =============================================================================
# DISPATCH TABLE — grown one whitepaper at a time.
# Every entry maps 'PAPER_N' -> a callable (dataset) -> {value, formula, ...}
# =============================================================================
DISPATCH = {}


def _register(paper_id):
    """Decorator: registers a paper's calculator surface into DISPATCH."""
    def _wrap(fn):
        DISPATCH[paper_id] = fn
        return fn
    return _wrap

def calc(paper_id, dataset=None):
    """Primary public interface. Look up a paper's dispatch and evaluate it."""
    if paper_id not in DISPATCH:
        return {
            'value': None,
            'formula': None,
            'source': paper_id,
            'residual_pct': None,
            'status': 'OPEN_NOT_YET_WIRED',
        }
    return DISPATCH[paper_id](dataset or {})


def list_wired():
    """Return sorted list of PAPER_Ns currently wired (alias-safe: suffixed ids
    like PAPER_1209X sort by numeric stem then suffix - v0.412.0 fix of the
    public-API crash found by independent evaluation)."""
    def _key(p):
        tail = p.split('_', 1)[1] if '_' in p else p
        digits = ''
        for ch in tail:
            if ch.isdigit():
                digits += ch
            else:
                break
        return (int(digits) if digits else 10**9, tail)
    return sorted(DISPATCH.keys(), key=_key)


def wired_count():
    """Return count of wired papers."""
    return len(DISPATCH)



