    def _is_prime(k):
        if k < 2:
            return False
        for d in range(2, int(k ** 0.5) + 1):
            if k % d == 0:
                return False
        return True
    primes = [p for p in range(2, p_max + 1) if _is_prime(p)]
    total, count = 0.0, 0
